//! Shared fixture helpers.
//!
//! The fixture is a ~300-byte ONNX graph committed under `tests/fixtures/`,
//! regenerated by `cargo run -p cf-gears-onnx-runner --example
//! generate_test_fixture`. See `tests/fixtures/README.md` for its provenance.
//!
//! Everything here works with **no network and no files outside the repo**,
//! which is what lets these suites run in CI where the real 528 MB models
//! cannot.

#![allow(dead_code, clippy::unwrap_used, clippy::expect_used)]

use std::collections::BTreeMap;
use std::path::PathBuf;

use onnx_runner::config::{ModelConfig, OutputDtype};
use onnx_runner::domain::{NoopMetrics, OnnxRunnerMetricsPort};
use toolkit_security::SecurityContext;
use uuid::Uuid;

/// SHA-256 of `tests/fixtures/tiny.onnx`. Printed by the generator; update it
/// there and here together if the graph ever changes.
pub const FIXTURE_SHA256: &str = "234e1ae7863de405221537bf1e8d7fc7219783870d123d00effd781653cfbff2";

/// SHA-256 of `tests/fixtures/other.onnx`, the second fixture. Same rule as
/// [`FIXTURE_SHA256`]: the generator prints it, update both together.
pub const OTHER_FIXTURE_SHA256: &str =
    "979ea12f98024057501e1d5a3225de39eddae68d76ce1995ae99b932eb3bb266";

pub const MODEL_ID: &str = "tiny";
pub const OTHER_MODEL_ID: &str = "other";

pub fn fixtures_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

pub fn tokenizer_path() -> PathBuf {
    fixtures_dir().join("tokenizer.json")
}

pub fn ctx() -> SecurityContext {
    SecurityContext::builder()
        .subject_id(Uuid::new_v4())
        .subject_tenant_id(Uuid::new_v4())
        .build()
        .expect("valid SecurityContext")
}

/// Fails fast when no ONNX Runtime is configured.
///
/// Without this, a developer running `cargo test` with `ORT_DYLIB_PATH` unset
/// would not get a failure — they would get a **hang**, because `ort`
/// 2.0.0-rc.12 blocks forever instead of erroring on a runtime it cannot load
/// (see `libs/ort-bootstrap`). An instant, legible error is worth the six lines.
///
/// Called from [`fixture_config`], so every test that builds a session gets it
/// without having to remember.
pub fn require_onnxruntime() {
    let configured = std::env::var("ORT_DYLIB_PATH")
        .ok()
        .filter(|p| !p.is_empty());
    let path = configured.as_deref().unwrap_or("");

    assert!(
        !path.is_empty() && std::path::Path::new(path).exists(),
        "ORT_DYLIB_PATH is unset or points at a missing file ({path:?}).\n\
         These tests load a real ONNX session, and `ort` hangs rather than erroring \
         when it cannot load a runtime — so this fails now instead of never.\n\
         Fix:  export ORT_DYLIB_PATH=\"$(bash scripts/fetch-onnxruntime.sh --path)\""
    );
}

/// The fixture's true contract: two inputs and two outputs, two dtypes.
pub fn fixture_config() -> ModelConfig {
    require_onnxruntime();
    ModelConfig {
        model_id: MODEL_ID.to_owned(),
        model_dir: fixtures_dir(),
        model_file: "tiny.onnx".to_owned(),
        tokenizer_file: "tokenizer.json".to_owned(),
        sha256: FIXTURE_SHA256.to_owned(),
        skip_checksum: false,
        expected_inputs: vec!["ids".to_owned(), "weights".to_owned()],
        expected_outputs: vec!["ids_out".to_owned(), "scores".to_owned()],
        output_dtypes: output_dtypes(),
        replicas: 1,
        intra_threads: 1,
        ..ModelConfig::default()
    }
}

pub fn output_dtypes() -> BTreeMap<String, OutputDtype> {
    [
        ("ids_out".to_owned(), OutputDtype::I64),
        ("scores".to_owned(), OutputDtype::F32),
    ]
    .into_iter()
    .collect()
}

/// The fixture config with one field changed.
/// The second fixture's contract: one input fewer in common with the first
/// than any two copies of the same graph would be.
///
/// Different tensor names, different dtypes (`u8` and `bool`), and a different
/// tokenizer-free shape. Sharing `tokenizer.json` with the first is fine — the
/// tokenizer is per-model configuration, not part of what makes the two graphs
/// distinct.
pub fn other_fixture_config() -> ModelConfig {
    require_onnxruntime();
    ModelConfig {
        model_id: OTHER_MODEL_ID.to_owned(),
        model_dir: fixtures_dir(),
        model_file: "other.onnx".to_owned(),
        tokenizer_file: "tokenizer.json".to_owned(),
        sha256: OTHER_FIXTURE_SHA256.to_owned(),
        skip_checksum: false,
        expected_inputs: vec!["tokens".to_owned(), "marks".to_owned()],
        expected_outputs: vec!["tokens_out".to_owned(), "marks_out".to_owned()],
        output_dtypes: other_output_dtypes(),
        replicas: 1,
        intra_threads: 1,
        ..ModelConfig::default()
    }
}

pub fn other_output_dtypes() -> BTreeMap<String, OutputDtype> {
    [
        ("tokens_out".to_owned(), OutputDtype::U8),
        ("marks_out".to_owned(), OutputDtype::Bool),
    ]
    .into_iter()
    .collect()
}

pub fn other_fixture_with(mutate: impl FnOnce(&mut ModelConfig)) -> ModelConfig {
    let mut cfg = other_fixture_config();
    mutate(&mut cfg);
    cfg
}

/// Resident set size of this process, in kilobytes.
///
/// `ps` rather than a crate: this is recorded for the multi-model startup
/// numbers, not asserted on, so a dependency would not earn its place. Returns
/// `None` wherever `ps` is unavailable or unparseable rather than failing a
/// test over a diagnostic.
#[must_use]
pub fn resident_kb() -> Option<u64> {
    let out = std::process::Command::new("ps")
        .args(["-o", "rss=", "-p", &std::process::id().to_string()])
        .output()
        .ok()?;
    String::from_utf8(out.stdout).ok()?.trim().parse().ok()
}

pub fn fixture_with(mutate: impl FnOnce(&mut ModelConfig)) -> ModelConfig {
    let mut cfg = fixture_config();
    mutate(&mut cfg);
    cfg
}

/// A metrics port that records nothing, for tests that are not about metrics.
#[must_use]
pub fn no_metrics() -> std::sync::Arc<dyn OnnxRunnerMetricsPort> {
    std::sync::Arc::new(NoopMetrics)
}

/// One recorded inference, as the metrics port saw it.
#[derive(Debug, Clone)]
pub struct RecordedInference {
    pub model_id: String,
    pub outcome: onnx_runner::domain::InferenceOutcome,
    pub queue_wait: std::time::Duration,
    pub execution: std::time::Duration,
}

/// A metrics port that remembers what it was told.
///
/// Asserting through a port rather than by scraping an exporter keeps the tests
/// about *what is measured* rather than about OpenTelemetry's plumbing.
#[derive(Default)]
pub struct RecordingMetrics {
    pub inferences: std::sync::Mutex<Vec<RecordedInference>>,
    pub tokenizations: std::sync::Mutex<Vec<(String, std::time::Duration)>>,
    pub loads: std::sync::Mutex<Vec<(String, String, u64)>>,
    pub rebuilds: std::sync::Mutex<Vec<(String, bool)>>,
    pub in_flight_deltas: std::sync::Mutex<Vec<(String, i64)>>,
}

impl RecordingMetrics {
    #[must_use]
    pub fn inferences(&self) -> Vec<RecordedInference> {
        self.inferences.lock().expect("not poisoned").clone()
    }

    /// Net in-flight after every delta — must return to zero once calls finish.
    #[must_use]
    pub fn net_in_flight(&self) -> i64 {
        self.in_flight_deltas
            .lock()
            .expect("not poisoned")
            .iter()
            .map(|(_, d)| *d)
            .sum()
    }
}

impl OnnxRunnerMetricsPort for RecordingMetrics {
    fn record_inference(
        &self,
        model_id: &str,
        outcome: onnx_runner::domain::InferenceOutcome,
        queue_wait: std::time::Duration,
        execution: std::time::Duration,
    ) {
        self.inferences
            .lock()
            .expect("not poisoned")
            .push(RecordedInference {
                model_id: model_id.to_owned(),
                outcome,
                queue_wait,
                execution,
            });
    }

    fn record_tokenize(
        &self,
        model_id: &str,
        _outcome: onnx_runner::domain::InferenceOutcome,
        elapsed: std::time::Duration,
    ) {
        self.tokenizations
            .lock()
            .expect("not poisoned")
            .push((model_id.to_owned(), elapsed));
    }

    fn record_in_flight_delta(&self, model_id: &str, delta: i64) {
        self.in_flight_deltas
            .lock()
            .expect("not poisoned")
            .push((model_id.to_owned(), delta));
    }

    fn record_model_load(
        &self,
        model_id: &str,
        outcome: onnx_runner::domain::LoadOutcome,
        _elapsed: std::time::Duration,
        resident_bytes: u64,
    ) {
        self.loads.lock().expect("not poisoned").push((
            model_id.to_owned(),
            outcome.as_label().to_owned(),
            resident_bytes,
        ));
    }

    fn record_session_rebuild(&self, model_id: &str, succeeded: bool) {
        self.rebuilds
            .lock()
            .expect("not poisoned")
            .push((model_id.to_owned(), succeeded));
    }
}
